"use strict";(globalThis.webpackChunkdoqumentation=globalThis.webpackChunkdoqumentation||[]).push([[8894],{30030(a,n,e){e.r(n),e.d(n,{assets:()=>s,contentTitle:()=>r,default:()=>l,frontMatter:()=>k,metadata:()=>i,toc:()=>m});const i=JSON.parse('{"id":"learning/courses/integrating-quantum-and-high-performance-computing/next-steps","title":"Langkah seterusnya","description":"Pelajaran ini mengkaji keadaan pengkomputeran kuantum dan cara manusia mendekati kelebihan kuantum.","source":"@site/i18n/ms/docusaurus-plugin-content-docs/current/learning/courses/integrating-quantum-and-high-performance-computing/next-steps.mdx","sourceDirName":"learning/courses/integrating-quantum-and-high-performance-computing","slug":"/learning/courses/integrating-quantum-and-high-performance-computing/next-steps","permalink":"/learning/courses/integrating-quantum-and-high-performance-computing/next-steps","draft":false,"unlisted":false,"editUrl":"https://github.com/JanLahmann/doQumentation/tree/main/docs/learning/courses/integrating-quantum-and-high-performance-computing/next-steps.mdx","tags":[],"version":"current","frontMatter":{"title":"Langkah seterusnya","sidebar_label":"Langkah seterusnya","description":"Pelajaran ini mengkaji keadaan pengkomputeran kuantum dan cara manusia mendekati kelebihan kuantum.","notebook_path":"learning/courses/integrating-quantum-and-high-performance-computing/next-steps.ipynb"},"sidebar":"tutorialsSidebar","previous":{"title":"SQD dan SKQD","permalink":"/learning/courses/integrating-quantum-and-high-performance-computing/sqd-skqd"},"next":{"title":"Peperiksaan | Mengintegrasikan pengkomputeran kuantum dan prestasi tinggi","permalink":"/learning/courses/integrating-quantum-and-high-performance-computing/exam"}}');var t=e(74848),u=e(28453);const k={title:"Langkah seterusnya",sidebar_label:"Langkah seterusnya",description:"Pelajaran ini mengkaji keadaan pengkomputeran kuantum dan cara manusia mendekati kelebihan kuantum.",notebook_path:"learning/courses/integrating-quantum-and-high-performance-computing/next-steps.ipynb"},r="Pandangan dan hala tuju masa depan {#pandangan-dan-hala-tuju-masa-depan}",s={},m=[{value:"Mengapa sekarang?",id:"mengapa-sekarang",level:3},{value:"5.1 Gambaran besar",id:"gambaran-besar",level:2},{value:"Idea-idea besar",id:"idea-idea-besar",level:2},{value:"Pandangan IBM untuk masa depan",id:"pandangan-ibm-untuk-masa-depan",level:2},{value:"Ringkasan",id:"ringkasan",level:2}];function g(a){const n={a:"a",h1:"h1",h2:"h2",h3:"h3",header:"header",img:"img",li:"li",p:"p",ul:"ul",...(0,u.R)(),...a.components};return(0,t.jsxs)(t.Fragment,{children:["\n","\n",(0,t.jsx)(n.header,{children:(0,t.jsx)(n.h1,{id:"pandangan-dan-hala-tuju-masa-depan",children:"Pandangan dan hala tuju masa depan"})}),"\n",(0,t.jsx)(n.p,{children:"Setakat ini, kita telah mempelajari tentang motivasi untuk menggunakan kedua-dua pengkomputeran prestasi tinggi (HPC) dan pengkomputeran kuantum untuk menyelesaikan masalah saintifik. Kita telah mendefinisikan sumber pengkomputeran klasik dan kuantum, termasuk CPU, GPU, dan QPU, serta membincangkan cara menskalakan dan menguruskannya menggunakan teknik seperti penskalaan menegak dan mendatar, penjadualan, dan pengurusan beban kerja. Selain itu, kita telah meneroka model pengaturcaraan untuk QPU (seperti Circuit kuantum dan primitif seperti Sampler dan Estimator) dan komputer klasik, termasuk amalan pengaturcaraan selari dengan MPI, yang merupakan alat berkuasa dalam pengkomputeran heterogen kuantum-klasik. Akhirnya, kita telah mengkaji dan mengamalkan algoritma berasaskan pensampelan kuantum yang canggih, seperti Sample-based Quantum Diagonalization (SQD) dan Sample-based Krylov Quantum Diagonalization (SKQD). Algoritma-algoritma ini memanfaatkan kaedah subruang untuk menganggarkan tenaga keadaan asas molekul dan bahan dengan tepat dengan menyediakan dan mensampling keadaan kuantum, yang mentakrifkan subruang untuk pendiagonalan klasik, gabungan model pengaturcaraan yang berbeza pada set sumber heterogen. Dengan konsep-konsep asas pengkomputeran kuantum dan klasik ini, kita tidak lagi bercakap tentang satu menggantikan yang lain, tetapi tentang mewujudkan sistem bersepadu yang berkuasa yang bekerja secara sinergi \u2014 gabungan yang bersedia untuk membawa fajar kelebihan kuantum."}),"\n",(0,t.jsx)(n.h3,{id:"mengapa-sekarang",children:"Mengapa sekarang?"}),"\n",(0,t.jsxs)(n.p,{children:['Komuniti sudah melangkau pencapaian "utiliti kuantum" \u2014 di mana komputer kuantum pertama kali terbukti sebagai alat saintifik yang berguna yang mampu melakukan pengiraan melebihi simulasi brute-force klasik. Era utiliti ini bermula dengan ',(0,t.jsx)(n.a,{href:"https://www.nature.com/articles/s41586-023-06096-3",children:"kertas utiliti"}),' yang terkenal yang ditampilkan di halaman kulit Nature pada 2023, dan kemudiannya merangkumi berpuluh-puluh penerbitan oleh rakan kongsi, klien, dan penyelidik di IBM Quantum\xae. Kini, fokus telah beralih kepada sempadan kritikal seterusnya: mencapai kelebihan kuantum. Untuk masa yang lama, istilah "kelebihan kuantum" menderita akibat definisi yang tidak tepat. ',(0,t.jsx)(n.a,{href:"https://arxiv.org/abs/2506.20658",children:"Kertas ini"})," telah mengemukakan definisi konkrit, yang akan kita gunakan di sini. Khususnya, kelebihan kuantum merujuk kepada pelaksanaan tugas pemprosesan maklumat pada perkakasan kuantum yang memenuhi dua kriteria penting:"]}),"\n",(0,t.jsx)(n.p,{children:"i) Ketepatan output boleh disahkan secara ketat, dan"}),"\n",(0,t.jsx)(n.p,{children:"ii) Ia dilaksanakan dengan pemisahan kuantum yang secara nyata menawarkan kecekapan, keberkesanan kos, atau ketepatan yang lebih tinggi berbanding apa yang boleh dicapai dengan pengkomputeran klasik sahaja."}),"\n",(0,t.jsx)(n.p,{children:"Dijangkakan bahawa kelebihan kuantum akan mula muncul menjelang akhir 2026 dan ia akan berlaku melalui pemanfaatan sumber kuantum dan HPC bersama-sama. Pelajaran ini menggariskan visi teras untuk paradigma baru ini, memperincikan idea-idea utama ke hadapan, dan menyampaikan pandangan masa depan yang berasaskan kerangka yang boleh disahkan dan bebas platform untuk menunjukkan dan merealisasikan kelebihan kuantum yang sebenar."}),"\n",(0,t.jsx)(n.h2,{id:"gambaran-besar",children:"5.1 Gambaran besar"}),"\n",(0,t.jsx)(n.p,{children:'Buat pertama kalinya, kita menyaksikan titik perubahan yang ketara dalam sejarah pengkomputeran - era pengkomputeran super berpusatkan kuantum (QCSC), paradigma baru yang mengintegrasikan unit pemprosesan kuantum (QPU) dengan superkomputer klasik dengan rapat. Visinya bukan untuk sistem kuantum menggantikan sistem klasik, tetapi untuk menunjukkan bahawa seni bina heterogen ini \u2014 di mana "kuantum ditambah klasik" boleh mengatasi prestasi klasik sahaja \u2014 adalah laluan ke hadapan yang paling berkuasa. Dalam model ini, QPU dibayangkan sebagai co-pemproses khusus, bekerja bersama CPU dan GPU untuk menangani masalah pengkomputeran yang tidak dapat diselesaikan oleh komputer klasik.'}),"\n",(0,t.jsx)(n.p,{children:"Potensi penuh seni bina baru ini hanya boleh direalisasikan dengan meletakkan alat-alat berkuasa ini ke tangan seramai mungkin pengguna. Visi ini sudah mengambil bentuk melalui penempatan sistem kuantum di pusat-pusat pengkomputeran prestasi tinggi (HPC) yang mapan dan pembangunan perisian, seperti plugin Slurm kuantum, yang mempermudah integrasi mereka ke dalam aliran kerja klasik yang sedia ada. Dengan menjadikan sistem heterogen ini lebih mudah diakses kepada komuniti penyelidikan yang lebih luas, kita memupuk persekitaran yang diperlukan untuk inovasi dan penemuan."}),"\n",(0,t.jsx)(n.p,{children:"Strategi menggabungkan teknologi bersepadu dengan asas pengguna yang luas inilah cara kita percaya komuniti akan mencapai kelebihan kuantum dalam masa terdekat. Kelebihan kuantum bukan satu pencapaian tunggal yang muktamad tetapi satu proses \u2014 jujukan demonstrasi yang semakin teguh yang akan diteliti, direproduksi, dan dicabar oleh komuniti sehingga konsensus saintifik dicapai. Ini adalah laluan untuk menunjukkan, menjelang akhir 2026, contoh-contoh pertama yang boleh dipercayai dan boleh disahkan di mana cara pengkomputeran baru ini menyelesaikan masalah praktikal dengan lebih cekap, berkesan kos, atau tepat berbanding apa yang boleh dicapai dengan pengkomputeran klasik sahaja."}),"\n",(0,t.jsx)(n.p,{children:(0,t.jsx)(n.img,{alt:"Rajah yang menunjukkan kos simulasi sebagai fungsi peningkatan kerumitan Circuit untuk kedua-dua komputer klasik dan komputer kuantum dengan pengurangan ralat. Setelah lengkung bersilang, ruang di antaranya sepadan dengan kelebihan kuantum.",src:e(89816).A+"",width:"793",height:"540"})}),"\n",(0,t.jsx)(n.h2,{id:"idea-idea-besar",children:"Idea-idea besar"}),"\n",(0,t.jsx)(n.p,{children:"Untuk merealisasikan visi ini, beberapa soalan dan idea kritikal mesti ditangani."}),"\n",(0,t.jsxs)(n.ul,{children:["\n",(0,t.jsxs)(n.li,{children:["\n",(0,t.jsx)(n.p,{children:"Pembahagian beban kerja yang optimum: Dari sisi perisian, cabaran terletak pada pengurusan aliran kerja hibrid yang kompleks. Mengorkestrakan pelaksanaan tugas yang lancar merentasi sumber kuantum dan klasik memerlukan alat yang canggih. Ini merangkumi Middleware Kuantum-HPC dan Infrastruktur Runtime yang direka untuk mengendalikan penjadualan kerja, pengurusan sumber, dan aliran data dalam persekitaran heterogen ini. Selain itu, membangunkan teknik untuk memparalelkan Circuit kuantum secara berkesan atau memecahnya kepada bahagian-bahagian yang lebih kecil dan boleh diurus adalah penting untuk memaksimumkan utiliti perkakasan kuantum hari ini."}),"\n"]}),"\n",(0,t.jsxs)(n.li,{children:["\n",(0,t.jsx)(n.p,{children:'Toleransi ralat peringkat sistem: Penyelesaian muktamad untuk melindungi maklumat kuantum daripada bunyi adalah pengkomputeran kuantum toleran ralat (FTQC), di mana maklumat dikodkan ke dalam "qubit logik" yang teguh. Walaupun kod pembetulan ralat low-density parity-check (qLDPC) kuantum yang baru muncul menawarkan laluan untuk mengurangkan overhead sumber yang sangat besar yang diperlukan, pelaksanaan toleransi ralat penuh tidak dijangka boleh dilaksanakan dalam jangka masa terdekat. Pada masa yang sama, pengurangan ralat menggunakan pasca-pemprosesan klasik untuk mengurangkan atau menghapuskan bias dalam pengiraan yang disebabkan oleh bunyi, yang juga merupakan elemen kritikal dalam mencapai sistem kuantum toleran ralat peringkat sistem. Kaedah pengurangan ralat yang berkuasa sudah digunakan sebagai perkhidmatan, menunjukkan kekuatan seni bina QCSC. Contohnya:'}),"\n",(0,t.jsxs)(n.ul,{children:["\n",(0,t.jsxs)(n.li,{children:[(0,t.jsx)(n.a,{href:"/guides/algorithmiq-tem",children:"Tensor Network Error Mitigation"})," (TEM) Algorithmiq menguruskan bunyi dalam pasca-pemprosesan perisian, memanfaatkan sumber HPC klasik untuk memperluas jangkauan QPU semasa."]}),"\n",(0,t.jsxs)(n.li,{children:[(0,t.jsx)(n.a,{href:"/guides/qedma-qesem",children:"Quantum Error Suppression and Error Mitigation"})," (QESEM) Qedma menggabungkan penindasan ralat peringkat perkakasan dengan pengurangan untuk meningkatkan kebolehpercayaan pengiraan kuantum pada skala besar."]}),"\n"]}),"\n"]}),"\n",(0,t.jsxs)(n.li,{children:["\n",(0,t.jsx)(n.p,{children:"Mendemokratikkan akses: Menjadikan sistem hibrid yang berkuasa ini mudah diakses secara luas adalah kunci untuk mempercepatkan inovasi. Ini sudah direalisasikan melalui penempatan fizikal sistem kuantum di pusat HPC dan pelepasan plugin Slurm untuk integrasi yang dipermudahkan. Untuk mempermudah integrasi ini, kedua-dua syarikat telah melepaskan plugin Slurm, supaya beban kerja kuantum boleh diuruskan dengan pengatur jadual HPC standard. Selain itu, timbunan perisian komprehensif seperti Qiskit menyediakan persekitaran runtime berasaskan awan untuk pelaksanaan Circuit kuantum berlatensi rendah, mengorkestrakan tugas hibrid yang kompleks dan menyediakan alat untuk penyusunan, pengoptimuman, dan pengurangan ralat. Perkakasan kuantum akses terbuka dan pakej pembangunan sumber terbuka pastinya akan memainkan peranan kritikal."}),"\n"]}),"\n"]}),"\n",(0,t.jsx)(n.h2,{id:"pandangan-ibm-untuk-masa-depan",children:"Pandangan IBM untuk masa depan"}),"\n",(0,t.jsxs)(n.p,{children:[(0,t.jsx)(n.a,{href:"https://www.ibm.com/quantum/hardware#roadmap",children:"Peta Jalan Pembangunan IBM Quantum"})," adalah demonstrasi yang baik tentang gambaran besar dan idea-idea besar ini."]}),"\n",(0,t.jsx)(n.p,{children:(0,t.jsx)(n.img,{alt:"Peta Jalan Pembangunan IBM Quantum",src:e(97895).A+"",width:"960",height:"536"})}),"\n",(0,t.jsx)(n.p,{children:'Peta jalan perkakasan IBM Quantum didorong oleh fokus pada peningkatan skala dan sambungan qubit. Siri Nighthawk (2025-2028) menggunakan seni bina kekisi segi empat sama baru untuk meningkatkan sambungan, sementara pemproses Loon (2025) memperkenalkan "c-couplers" untuk membolehkan sambungan qubit bukan tempatan, yang kritikal untuk pengkomputeran kuantum toleran ralat (FTQC). Peta jalan ini mencapai kemuncaknya dalam sistem IBM Quantum Starling (2029) dan Blue Jay (2033+), yang direka untuk menyampaikan pengiraan berskala besar dan toleran ralat dengan berjuta-juta gate dan beribu-ribu qubit logik.'}),"\n",(0,t.jsx)(n.p,{children:"Strategi perisian dan middleware dibina atas empat objektif utama: melaksanakan dengan tepat, mengorkestrakan beban kerja, menemui algoritma baru, dan menggunakannya untuk kes penggunaan tertentu. Peta jalan merangkumi penambahbaikan berterusan seperti Circuit dinamik berskala utiliti (2025) dan alat profil baru (2026) untuk memastikan pelaksanaan yang cekap. Untuk orkestasi beban kerja, C-API (2025) dan pemecut aliran kerja masa depan (2027) akan mengintegrasikan pengkomputeran kuantum dan HPC klasik. Selanjutnya, IBM\xae akan memperkenalkan alat pemetaan utiliti (2026) dan perpustakaan Circuit baru (2029) untuk memudahkan penemuan dan penerapan algoritma baru."}),"\n",(0,t.jsx)(n.h2,{id:"ringkasan",children:"Ringkasan"}),"\n",(0,t.jsx)(n.p,{children:"Kita telah meneroka gambaran besar dan idea-idea besar di sebalik matlamat QCSC, dan kita melihat peta jalan IBM mengenai pembangunan dan inovasi pengkomputeran kuantum. Perjalanan ini, seperti yang kita lihat, adalah maraton, bukan pecut. Walaupun IBM komited untuk menghantar komputer kuantum yang semakin berkuasa, kemajuan kita hanyalah satu bahagian daripada persamaan. Adalah penting bahawa komuniti kuantum terus membangunkan algoritma baru, membuka jalan untuk aplikasi yang benar-benar akan membawa pengkomputeran kuantum yang berguna kepada dunia."}),"\n",(0,t.jsx)(n.p,{children:"Untuk mencapai ini, kita mesti bekerja bersama. Ini bermakna menetapkan masalah penanda aras yang standard dengan bantuan pakar klasik untuk memastikan relevansi dan keadilan. Ia juga memerlukan penerbitan metodologi dan set data terperinci untuk membolehkan kebolehreproduksian, dan mengekalkan papan pemimpin akses terbuka untuk menjejak kemajuan kolektif kita."}),"\n",(0,t.jsx)(n.p,{children:"Tidak pernah ada masa yang lebih menarik untuk menjadi sebahagian daripada komuniti ini. Dengan mengamalkan amalan terbaik ini dan meneruskan penerokaan kita, kita boleh bekerja bersama untuk merealisasikan potensi penuh kelebihan kuantum."})]})}function l(a={}){const{wrapper:n}={...(0,u.R)(),...a.components};return n?(0,t.jsx)(n,{...a,children:(0,t.jsx)(g,{...a})}):g(a)}},89816(a,n,e){e.d(n,{A:()=>i});const i=e.p+"assets/images/advantage-f7fc7a67f0f1aac33e4c95b7965b10c0.svg"},97895(a,n,e){e.d(n,{A:()=>i});const i=e.p+"assets/images/roadmap-c4a476cff4c185739f3c99c69c717523.svg"},28453(a,n,e){e.d(n,{R:()=>k,x:()=>r});var i=e(96540);const t={},u=i.createContext(t);function k(a){const n=i.useContext(u);return i.useMemo(function(){return"function"==typeof a?a(n):{...n,...a}},[n,a])}function r(a){let n;return n=a.disableParentContext?"function"==typeof a.components?a.components(t):a.components||t:k(a.components),i.createElement(u.Provider,{value:n},a.children)}}}]);